from flask import Flask, render_template_string

app = Flask(__name__)

HTML = r'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Электрический склад</title><style>
*{box-sizing:border-box}:root{--bg:#eef2f3;--panel:#f8faf9;--ink:#34454b;--muted:#718087;--line:#ccd7d8;--accent:#527d83;--soft:#e0ebea}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:var(--bg);color:var(--ink)}header{background:#536a70;color:#f8fbfb;padding:14px 20px}.top{max-width:1250px;margin:auto;display:flex;justify-content:space-between;align-items:center;gap:15px}h1{margin:0;font-size:25px}.lang button,.back,.save{border:1px solid var(--line);border-radius:8px;padding:8px 12px;cursor:pointer}.workspace{max-width:1250px;margin:auto;padding:18px 14px;display:grid;grid-template-columns:145px 1fr;gap:18px}.side{display:flex;flex-direction:column;align-items:center;gap:12px}.diamond-button{width:112px;height:112px;border:0;background:transparent;cursor:pointer}.diamond{width:80px;height:80px;margin:16px auto;background:#f7faf9;border:2px solid var(--line);border-radius:13px;transform:rotate(45deg);display:flex;align-items:center;justify-content:center}.diamond-inner{width:102px;transform:rotate(-45deg);text-align:center;font-weight:700;font-size:13px}.icon{display:block;font-size:20px}.content{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:22px}.page{display:none}.page.active{display:block}.subtitle{color:var(--muted)}.box{border:1px solid var(--line);border-radius:12px;padding:20px;background:#fff;min-height:350px}.machine-grid{display:grid;grid-template-columns:repeat(4,minmax(105px,1fr));gap:12px}.machine,.detail-tile{min-height:76px;border:1px solid var(--line);border-radius:10px;background:#f2f6f5;color:var(--ink);font-weight:700;cursor:pointer}.detail-grid{display:grid;grid-template-columns:repeat(2,minmax(180px,1fr));gap:16px;max-width:620px}.detail-tile{min-height:110px}.fault-form{margin-top:18px;padding:16px;border:1px solid var(--line);border-radius:12px;background:#fff}.fault-form label{display:block;font-weight:700;margin:12px 0 5px}.fault-form input,.fault-form textarea,.fault-form select{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;background:#fbfdfc}.fault-form textarea{min-height:70px}.save{margin-top:14px;background:var(--accent);color:white;font-weight:700}.records{margin-top:18px;display:grid;gap:10px}.record{background:#fff;border:1px solid var(--line);border-radius:10px;padding:12px}.record img{max-width:180px;max-height:130px;border-radius:8px;margin-top:8px}.record-date{font-weight:700}.stats{margin:15px 0;padding:10px;background:var(--soft);border-radius:8px;font-weight:700}
@media(max-width:720px){.workspace{grid-template-columns:105px 1fr;gap:8px;padding:10px 6px}.diamond-button{width:92px;height:92px}.diamond{width:64px;height:64px}.diamond-inner{width:86px;font-size:11px}.content{padding:14px 10px}.machine-grid{grid-template-columns:repeat(2,1fr);gap:8px}.detail-grid{grid-template-columns:1fr}h1{font-size:20px}}
</style></head><body><header><div class="top"><h1>⚡ <span id="appTitle"></span></h1><div class="lang"><button onclick="setLang('ru')">RU</button><button onclick="setLang('he')">עברית</button><button onclick="setLang('en')">EN</button></div></div></header><main class="workspace"><nav class="side"><button class="diamond-button" id="stockBtn" onclick="showPage('stock')"><div class="diamond"><div class="diamond-inner"><span class="icon">📦</span><span id="stockNav"></span></div></div></button><button class="diamond-button" id="machinesBtn" onclick="showPage('machines')"><div class="diamond"><div class="diamond-inner"><span class="icon">🏭</span><span id="machinesNav"></span></div></div></button></nav><section class="content">
<div id="stock" class="page active"><h2 id="stockTitle"></h2><div class="box">Здесь будем отдельно строить склад.</div></div>
<div id="machines" class="page"><h2 id="machinesTitle"></h2><p class="subtitle" id="machinesSub"></p><div class="machine-grid" id="machineGrid"></div></div>
<div id="machineDetail" class="page"><button class="back" onclick="showPage('machines')" id="backBtn"></button><h2 id="machineDetailTitle"></h2><div class="detail-grid"><button class="detail-tile" id="faultsTile" onclick="openFaults()"></button><button class="detail-tile" id="partsTile"></button></div></div>
<div id="faultPage" class="page"><button class="back" onclick="openMachine(currentMachineIndex)" id="faultBack"></button><h2 id="faultTitle"></h2><div class="stats" id="stats"></div><div class="fault-form"><label id="dateLabel"></label><input type="date" id="faultDate"><label id="areaLabel"></label><input id="faultArea" placeholder=""><label id="faultLabel"></label><textarea id="faultText"></textarea><label id="repairLabel"></label><textarea id="repairText"></textarea><label id="replaceLabel"></label><input id="replaceText"><label id="photoLabel"></label><input type="file" accept="image/*" capture="environment" id="faultPhoto"><button class="save" onclick="saveFault()" id="saveBtn"></button></div><div class="records" id="records"></div></div>
</section></main><script>
let lang=localStorage.getItem('elektrikaLang')||'ru',currentMachineIndex=null;
const machines={ru:['Кефель 5','Кефель 6','Кефель 7','Кефель 8','Кефель 9','Кефель 10','Кефель 11','Кефель 12','Кефель 13','C1','C2','C3','RDM','Машина печати','Машина формовки стаканов','Экструдер 4','Экструдер 5','Экструдер 6'],he:['כפל 5','כפל 6','כפל 7','כפל 8','כפל 9','כפל 10','כפל 11','כפל 12','כפל 13','C1','C2','C3','RDM','מכונת דפוס','מכונת כוסות','אקסטרודר 4','אקסטרודר 5','אקסטרודר 6'],en:['Kefel 5','Kefel 6','Kefel 7','Kefel 8','Kefel 9','Kefel 10','Kefel 11','Kefel 12','Kefel 13','C1','C2','C3','RDM','Printing Machine','Cup Forming Machine','Extruder 4','Extruder 5','Extruder 6']};
const T={ru:{title:'Электрический склад',stock:'Общий склад',machines:'Машины',choose:'Выберите машину',back:'← Назад к машинам',faults:'Поломки',parts:'Электрические части',faultBack:'← Назад к машине',date:'Дата поломки',area:'Часть машины',fault:'Какая поломка',repair:'Что сделал / ремонт',replace:'Замена электрической детали',photo:'Фотография поломки',save:'Сохранить поломку',stats:'Всего сохранённых поломок'},he:{title:'מחסן חשמל',stock:'מחסן כללי',machines:'מכונות',choose:'בחר מכונה',back:'← חזרה למכונות',faults:'תקלות',parts:'חלקי חשמל',faultBack:'← חזרה למכונה',date:'תאריך התקלה',area:'חלק במכונה',fault:'מה התקלקל',repair:'מה עשיתי / תיקון',replace:'החלפת חלק חשמלי',photo:'תמונה של התקלה',save:'שמור תקלה',stats:'סה״כ תקלות שמורות'},en:{title:'Electrical Warehouse',stock:'General Warehouse',machines:'Machines',choose:'Select a machine',back:'← Back to machines',faults:'Faults',parts:'Electrical Parts',faultBack:'← Back to machine',date:'Fault date',area:'Machine section',fault:'Fault description',repair:'What was done / repair',replace:'Electrical part replaced',photo:'Fault photo',save:'Save fault',stats:'Saved faults'}};
function showPage(p){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p).classList.add('active')}
function makeMachines(){let g=document.getElementById('machineGrid');g.innerHTML='';machines[lang].forEach((n,i)=>{let b=document.createElement('button');b.className='machine';b.textContent=n;b.onclick=()=>openMachine(i);g.appendChild(b)})}
function openMachine(i){currentMachineIndex=i;if(i>=15)return;document.getElementById('machineDetailTitle').textContent=machines[lang][i];showPage('machineDetail')}
function todayLocal(){let d=new Date(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return d.getFullYear()+'-'+m+'-'+day}
function openFaults(){document.getElementById('faultTitle').textContent=machines[lang][currentMachineIndex]+' — '+T[lang].faults;document.getElementById('faultDate').value=todayLocal();renderRecords();showPage('faultPage')}
function key(){return 'faults_machine_'+currentMachineIndex}
function saveFault(){let file=document.getElementById('faultPhoto').files[0];let finish=(photo)=>{let a=JSON.parse(localStorage.getItem(key())||'[]');a.unshift({date:document.getElementById('faultDate').value,area:document.getElementById('faultArea').value,fault:document.getElementById('faultText').value,repair:document.getElementById('repairText').value,replace:document.getElementById('replaceText').value,photo:photo||''});try{localStorage.setItem(key(),JSON.stringify(a))}catch(e){alert('Фотография слишком большая. Попробуйте фото меньшего размера.');return}document.getElementById('faultArea').value='';document.getElementById('faultText').value='';document.getElementById('repairText').value='';document.getElementById('replaceText').value='';document.getElementById('faultPhoto').value='';renderRecords()};if(file){let r=new FileReader();r.onload=e=>finish(e.target.result);r.readAsDataURL(file)}else finish('')}
function renderRecords(){let a=JSON.parse(localStorage.getItem(key())||'[]');document.getElementById('stats').textContent=T[lang].stats+': '+a.length;let r=document.getElementById('records');r.innerHTML='';a.forEach(x=>{let d=document.createElement('div');d.className='record';d.innerHTML='<div class="record-date">'+esc(x.date)+'</div><div><b>'+T[lang].area+':</b> '+esc(x.area)+'</div><div><b>'+T[lang].fault+':</b> '+esc(x.fault)+'</div><div><b>'+T[lang].repair+':</b> '+esc(x.repair)+'</div><div><b>'+T[lang].replace+':</b> '+esc(x.replace)+'</div>'+(x.photo?'<img src="'+x.photo+'">':'');r.appendChild(d)})}
function esc(s){let d=document.createElement('div');d.textContent=s||'';return d.innerHTML}
function setLang(l){lang=l;localStorage.setItem('elektrikaLang',l);let t=T[l];document.documentElement.dir=l==='he'?'rtl':'ltr';appTitle.textContent=t.title;stockNav.textContent=t.stock;machinesNav.textContent=t.machines;stockTitle.textContent=t.stock;machinesTitle.textContent=t.machines;machinesSub.textContent=t.choose;backBtn.textContent=t.back;faultsTile.textContent=t.faults;partsTile.textContent=t.parts;faultBack.textContent=t.faultBack;dateLabel.textContent=t.date;areaLabel.textContent=t.area;faultLabel.textContent=t.fault;repairLabel.textContent=t.repair;replaceLabel.textContent=t.replace;photoLabel.textContent=t.photo;saveBtn.textContent=t.save;makeMachines();if(currentMachineIndex!==null&&currentMachineIndex<15){machineDetailTitle.textContent=machines[l][currentMachineIndex];if(document.getElementById('faultPage').classList.contains('active')){faultTitle.textContent=machines[l][currentMachineIndex]+' — '+t.faults;renderRecords()}}}
setLang(lang);
</script></body></html>'''
@app.route('/')
def home(): return render_template_string(HTML)
if __name__ == '__main__': app.run(debug=True)
